func (v SummaryValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 3)

	var val tftypes.Value
	var err error

	attrTypes["aws"] = SummaryAwsType{
		basetypes.ObjectType{
			AttrTypes: SummaryAwsValue{}.AttributeTypes(ctx),
		},
	}.TerraformType(ctx)
	attrTypes["aws_without_doit"] = AwsWithoutDoitType{
		basetypes.ObjectType{
			AttrTypes: AwsWithoutDoitValue{}.AttributeTypes(ctx),
		},
	}.TerraformType(ctx)
	attrTypes["doit"] = SummaryDoitType{
		basetypes.ObjectType{
			AttrTypes: SummaryDoitValue{}.AttributeTypes(ctx),
		},
	}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 3)

		val, err = v.Aws.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["aws"] = val

		val, err = v.AwsWithoutDoit.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["aws_without_doit"] = val

		val, err = v.Doit.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["doit"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

